"""Endgame module: exact solvers + original, validated exercises.

Verification levels (shown to the learner, never hidden):
  * "kpk-bitbase": exact king+pawn-vs-king result from a bitbase generated by
    scripts/build_kpk.py with python-chess (win = forced queen/rook promotion that is not
    captured or stalemated; everything else is a draw).
  * "mate-search": forced mate within N moves proved by exhaustive search at load/test time.
  * "line-legal": a book line whose every move is legal and whose final claim is standard
    theory; the *result* of such a line is NOT machine-proved. Labelled as such.
"""
from __future__ import annotations

from functools import lru_cache
from pathlib import Path

import chess

BITBASE = Path(__file__).parent / "data" / "kpk.bin"
PAWNS = [chess.square(f, r) for f in range(4) for r in range(1, 7)]
TOTAL = len(PAWNS) * 64 * 64


@lru_cache(maxsize=1)
def _bits() -> bytes:
    return BITBASE.read_bytes()


def _get(i: int) -> bool:
    d = _bits()
    return bool(d[i // 8] >> (i % 8) & 1)


def _hflip(sq: int) -> int:
    return chess.square(7 - chess.square_file(sq), chess.square_rank(sq))


def kpk_normalise(board: chess.Board) -> tuple[int, int, int, bool] | None:
    """Return (wk, bk, pawn, pawn_side_to_move) with the pawn white and on files a-d, or None if not KPK."""
    pieces = board.piece_map()
    if len(pieces) != 3:
        return None
    pawn_sq = next((s for s, p in pieces.items() if p.piece_type == chess.PAWN), None)
    if pawn_sq is None:
        return None
    pawn_color = pieces[pawn_sq].color
    wk, bk = board.king(pawn_color), board.king(not pawn_color)
    if wk is None or bk is None:
        return None
    pawn_side_to_move = board.turn == pawn_color
    if pawn_color == chess.BLACK:  # flip vertically so the pawn side is White
        wk, bk, pawn_sq = (chess.square_mirror(s) for s in (wk, bk, pawn_sq))
    if chess.square_file(pawn_sq) > 3:  # mirror horizontally onto files a-d
        wk, bk, pawn_sq = (_hflip(s) for s in (wk, bk, pawn_sq))
    if not 1 <= chess.square_rank(pawn_sq) <= 6:
        return None
    return wk, bk, pawn_sq, pawn_side_to_move


def kpk_pawn_side_wins(board: chess.Board) -> bool | None:
    """True/False = the pawn's side can/cannot force promotion; None if not a KPK position."""
    n = kpk_normalise(board)
    if n is None:
        return None
    wk, bk, p, w = n
    i = (PAWNS.index(p) * 64 + wk) * 64 + bk
    return _get(i if w else TOTAL + i)


def mate_in(board: chess.Board, n: int) -> bool:
    """Can the side to move force checkmate within n of its own moves? (Exhaustive, exact.)"""
    if n <= 0:
        return board.is_checkmate()
    for move in list(board.legal_moves):
        board.push(move)
        try:
            if board.is_checkmate():
                return True
            if board.is_game_over():
                continue
            replies = list(board.legal_moves)
            if n == 1 or not replies:
                continue
            ok = True
            for reply in replies:
                board.push(reply)
                try:
                    if not mate_in(board, n - 1):
                        ok = False
                finally:
                    board.pop()
                if not ok:
                    break
            if ok:
                return True
        finally:
            board.pop()
    return False


# ------------------------------------------------------------- exercises --

from .endgames_data import EXERCISES, PROV  # noqa: E402

BY_ID = {e["id"]: e for e in EXERCISES}


def mate_distance(board: chess.Board, cap: int = 3) -> int | None:
    for n in range(1, cap + 1):
        if mate_in(board.copy(), n):
            return n
    return None


def _verification(ex: dict) -> str:
    if ex.get("verification"):
        return "line-legal"
    return {"mate": "mate-search", "win": "kpk-bitbase", "draw": "kpk-bitbase"}[ex["goal"][0]]


VERIFICATION_TEXT = {
    "mate-search": "Proved by exhaustive search: forced mate in the stated number of moves.",
    "kpk-bitbase": "Proved by an exact king-and-pawn bitbase generated for this project.",
    "line-legal": "Book line: every move is legal, but its theoretical result is standard theory, NOT machine-proved.",
}


def public_exercise(ex: dict, full: bool = False) -> dict:
    v = _verification(ex)
    out = {"id": ex["id"], "category": ex["category"], "title": ex["title"], "fen": ex["fen"],
           "goal": ex["goal"][0], "mate_in": ex["goal"][1] if ex["goal"][0] == "mate" else None,
           "concept": ex["concept"], "highlights": ex.get("highlights", []),
           "side_to_move": "white" if chess.Board(ex["fen"]).turn else "black",
           "verification": v, "verification_text": VERIFICATION_TEXT[v], "provenance": PROV}
    if full:
        out["hint"] = ex["hint"]
    return out


def _defender_reply(board: chess.Board, ex: dict) -> chess.Move | None:
    moves = list(board.legal_moves)
    if not moves:
        return None
    goal = ex["goal"][0]
    if goal == "mate":
        best, best_d = moves[0], -1
        for m in moves:
            board.push(m)
            d = mate_distance(board, 3) or 4
            board.pop()
            if d > best_d:
                best, best_d = m, d
        return best
    if goal == "win":  # defender plays on: prefer moves that keep the pawn alive longest (a drawing try)
        for m in moves:
            c = board.copy(); c.push(m)
            if kpk_pawn_side_wins(c) is False:
                return m
        return moves[0]
    # goal == draw: the learner defends; the scripted attacker tries the pawn push or king advance
    for m in moves:
        c = board.copy(); c.push(m)
        if c.piece_at(m.to_square) and c.piece_at(m.to_square).piece_type == chess.PAWN:
            return m
    return moves[0]


def check_move(ex: dict, fen: str, uci: str) -> dict:
    """Validate one learner move from `fen`; returns verdict, optional scripted reply and solved flag."""
    try:
        board = chess.Board(fen)
    except ValueError:
        return {"error": "Invalid position."}
    if board.status() != chess.STATUS_VALID:
        return {"error": "Illegal position."}
    try:
        move = chess.Move.from_uci(uci)
    except ValueError:
        return {"error": "Bad move."}
    if move not in board.legal_moves:
        return {"error": "Illegal move."}
    goal = ex["goal"]
    san = board.san(move)
    accepted, why, solved = True, "", False
    if goal[0] == "mate":
        d = mate_distance(board, goal[1]) if True else None
        if d is None:
            return {"error": "This position is not a forced mate within the exercise limit."}
        after = board.copy(); after.push(move)
        if after.is_checkmate():
            solved = True
        else:
            ok = (not after.is_game_over()) and d > 1 and all(
                mate_in(_push(after, r), d - 1) for r in list(after.legal_moves))
            accepted = ok
            if not ok:
                why = ("That move stalemates or draws." if after.is_stalemate() else
                       f"That move does not keep a forced mate in {d}.")
    elif goal[0] in ("win", "draw"):
        pawn_color = next((p.color for p in board.piece_map().values() if p.piece_type == chess.PAWN), None)
        after = board.copy(); after.push(move)
        if move.promotion:
            solved = goal[0] == "win" and not any(after.is_capture(m) for m in after.legal_moves) and any(after.legal_moves)
            accepted = solved
            why = "" if solved else "That promotion is captured or stalemates."
        else:
            res = kpk_pawn_side_wins(after)
            if res is None:  # pawn captured: K vs K, drawn
                accepted = goal[0] == "draw"
                solved = accepted
            elif goal[0] == "win":
                accepted = res
                why = "" if res else "That throws the win away: with best play the position is now a draw."
            else:
                accepted = not res
                why = "" if accepted else "That loses: with best play the pawn now promotes."
        _ = pawn_color
    else:  # line
        line = goal[1]
        key = lambda b: b.epd()  # noqa: E731
        b = chess.Board(ex["fen"])
        pos = None
        if key(b) == key(board):
            pos = 0
        for i, u in enumerate(line):
            b.push_uci(u)
            if key(b) == key(board):
                pos = i + 1
        if pos is None or pos >= len(line):
            return {"error": "This position is not on the book line."}
        accepted = line[pos] == uci
        why = "" if accepted else "That is not the book move here."
        if accepted:
            nxt = pos + 1
            solved = nxt >= len(line) - (0 if len(line) % 2 == 0 and False else 0)
            after = board.copy(); after.push(move)
            if nxt < len(line):
                rep = chess.Move.from_uci(line[nxt])
                san_r = after.san(rep)
                after.push(rep)
                solved = nxt + 1 >= len(line)
                return {"accepted": True, "san": san, "reply": {"uci": rep.uci(), "san": san_r},
                        "fen_after": after.fen(), "solved": solved, "why": ""}
            return {"accepted": True, "san": san, "reply": None, "fen_after": after.fen(), "solved": True, "why": ""}
    after = board.copy()
    if not accepted:
        return {"accepted": False, "san": san, "reply": None, "fen_after": fen, "solved": False, "why": why}
    after.push(move)
    reply = None
    if not solved and not after.is_game_over():
        rm = _defender_reply(after, ex)
        if rm:
            rep_san = after.san(rm)
            after.push(rm)
            reply = {"uci": rm.uci(), "san": rep_san}
            if goal[0] == "draw":
                res = kpk_pawn_side_wins(after)
                if res is None or after.is_game_over() or after.fullmove_number - chess.Board(ex["fen"]).fullmove_number >= 5:
                    solved = True
            if goal[0] == "mate" and after.is_game_over():
                solved = after.is_checkmate()
    return {"accepted": True, "san": san, "reply": reply, "fen_after": after.fen(), "solved": solved, "why": ""}


def _push(board: chess.Board, move: chess.Move) -> chess.Board:
    c = board.copy()
    c.push(move)
    return c
